import json
import os
import requests
import urllib.parse
from datetime import datetime, timedelta

# CONFIG
CONTRACT_FILE = '/tmp/contracts_cache.json'


def main(args: Args):
    queries = args.params['queries']
    # 3. Load Contracts (ללא שינוי)
    contracts = []
    if os.path.exists(CONTRACT_FILE):
        try:
            with open(CONTRACT_FILE, 'r') as f:
                raw = json.load(f)
            if "contracts" in raw: contracts = raw["contracts"]
            elif "output" in raw: contracts = json.loads(raw["output"]).get("contracts", [])
            elif "output:" in raw: contracts = json.loads(raw["output:"]).get("contracts", [])
            else:
                for v in raw.values():
                    if isinstance(v, str) and "contracts" in v:
                        contracts = json.loads(v).get("contracts", [])
                        break
        except: pass

    batch_context = {
        "incoming_queries": queries,
        "security_contracts": contracts
    }

    return {
        "batch_data_json": json.dumps(batch_context, indent=2),
        "count": len(queries)
    }
